import glob, json, urllib.request

for f in sorted(glob.glob("/tmp/dsh-spill-VCDDKt/session-e89ac6998274/*-web_fetch.txt")):
    txt = open(f).read()
    idx = txt.find("{")
    if idx != -1:
        try:
            d = json.loads(txt[idx:])
            for item in d.get("result", {}).get("data", []):
                t = item.get("title", "") + " | " + item.get("intro", "")
